css:
section{background:#e9e9ef} /* 面は2〜3階調のみ、アクセント色を定義しない */
.col,.card,figure{background:none;border:0;box-shadow:none;padding:0}
img{border-radius:0;display:block}
.cols{display:grid;grid-template-columns:repeat(3,1fr);gap:40px}
.more{display:block;text-align:right;font-size:18px;text-decoration:none} /* → 1文字だけ */
.dot{width:12px;height:12px;border-radius:50%;background:#fff;display:inline-block;margin-left:10px}
/* 地の色を強くする版 */
section.vivid{background:#8ee063;background-image:url(noise.png);background-blend-mode:multiply}
